-- Mod-authored great work descriptions, cs_CZ overlay.
-- Baseline in CivVAccess_GreatWorkDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_MISSING"] =
    "K tomuto výjimečnému dílu není k dispozici popis obrazu."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LITERATURE"] =
    "Spisovatelův psací stůl zblízka, slabě a vřele osvětlený svíčkami. Povrch pokrývají listy rukopisu psaného plynulým kurzivním písmem a přes ně napříč leží jediné šedé brko. U levého okraje leží srolovaný svitek převázaný červenou stuhou a v pravém horním rohu září skleněný kalamář."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MUSIC"] =
    "Šerý koncertní sál vřele osvětlený svíčkami. Uprostřed stojí dirigent v modrém kabátě a bílých punčochách se zvednutou taktovkou, obrácený k sedícímu orchestru hudebníků v napudrovaných parukách, kteří čtou z notových pultů. Pozlacená horní galerie zdobená reliéfními poli se táhne podél zadní stěny a vpravo plane velký svíčkový lustr, zatímco hlavy publika se v popředí rýsují jako tmavé tvary."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIRL_WITH_PEARL_EARRING"] =
    "Olejomalba nizozemského zlatého věku, jeden z nejmilovanějších portrétů západního umění. Mladá žena se přes rameno ohlíží a z jednoduchého tmavého pozadí se dívá tobě do očí, rty má lehce pootevřené, jako by se chystala promluvit. Má na hlavě modrozlatý turban, jehož látka jí splývá po zádech, a na uchu se zachycuje světlo na jediné velké perle ve tvaru slzy."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HENRY_VIII"] =
    "Olejový dvorní portrét z doby Tudorovců, podoba, která určila, jak si svět představuje Jindřicha VIII. Král stojí čelem k tobě v celé postavě, nohy široce rozkročené, široký v ramenou a těžký, jednu ruku opřenou o dýku u pasu. Na sobě má stříbrný kabátec zdobený drahokamy pod karmínovým pláštěm podšitým kožešinou, plochý klobouk s pery a zlaté řetězy a stojí na vzorovaném koberci mezi mramorovými sloupy."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HUNTERS_IN_THE_SNOW"] =
    "Vlámská renesanční olejomalba, zimní krajina při pohledu z vrcholu kopce. V popředí se hlubokým sněhem brodí tři unavení lovci se smečkou psů, s hlavami skloněnými a jedinou liškou jako kořistí. Pod nimi se pod šedozelenou oblohou rozkládá vesnice, na zamrzlých rybnících si hrají drobní bruslaři a v dálce se zdvihají zubaté štíty hor."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LES_DEMOISELLES"] =
    "Raně modernistická olejomalba, plátno, které odstartovalo kubismus. Pět nahých žen stojí a sedí v mělkém prostoru z ostrých růžových, bílých a modrých ploch a jejich těla jsou rozlámána na ostré hranaté tvary. Dvě tváře vpravo jsou namalovány jako africké masky, pruhované a zkreslené, zatímco ostatní zírají přímo před sebe velkýma mandlovýma očima. Při spodním okraji leží malá mísa s ovocem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LUNCHEON"] =
    "Francouzská impresionistická olejomalba přátel, kteří se zdržují po jídle. Čilá společnost v letním oblečení se tísní na balkoně u řeky pod pruhovanou oranžovobílou markýzou, povídá si, flirtuje a opírá se o zábradlí. Mladá žena v popředí si hraje s malým psem. Stůl je pokrytý lahvemi od vína, skleničkami a ovocem, to vše namalované teplými, volnými tahy slunečních barev."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MONA_LISA"] =
    "Italská renesanční olejomalba na dřevěné desce, pravděpodobně nejslavnější portrét na světě. Žena sedí se složenýma rukama, mírně natočená k tobě, před zamlženou krajinou s vinoucími se řekami a vzdálenými modrými horami. Její oči se setkávají přímo s tvýma, ten slavný pohled, který jako by tě sledoval, ať stojíš kdekoli. Její nepatrný poloúsměv je středem obrazu, namalovaný v měkkých hnědých a zelených tónech bez tvrdých obrysů, takže se zdá, že se její výraz proměňuje, čím déle se díváš."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUNDAY_AFTERNOON"] =
    "Pointilistická olejomalba vytvořená výhradně z drobných teček čisté barvy. Pařížané v nedělním oblečení odpočívají na slunném říčním trávníku, procházejí se se slunečníky, polehávají v trávě a venčí malé psy, za nimi na vodě plují plachetnice. Všichni jsou podivně strnulí a upjatí jako postavy na vlysu a světlo je rozloženo do třpytu zelených, oranžových a fialových teček."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VIEW_OF_TOLEDO"] =
    "Španělská renesanční olejomalba, jedna z prvních čistých krajin v západním umění a neobvykle temná. Španělské město Toledo na kopci se tyčí v dálce pod bouřlivou oblohou, jeho šedé věže a hradby ozařuje strašidelné stříbrné světlo. Zelené kopce se v popředí svažují k řece, celá scéna je namalována v hlubokých zelených a modročerných tónech, které působí spíš jako sen než jako denní světlo."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WATER_LILIES"] =
    "Francouzská impresionistická olejomalba ze slavného Monetova cyklu o zahradním jezírku v Giverny. Celé plátno je hladina vody, bez obzoru a bez břehu: vory zelených listů leknínů plují po modré a levandulové vodě poseté růžovými a červenými květy. Mraky a stromy se objevují jen jako měkké odrazy a tah štětce je tak volný, že se zdá, jako by vše plulo."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_STARRY_NIGHT"] =
    "Postimpresionistická olejomalba, jeden z nejznámějších obrazů moderního umění. Noční obloha plná pohybu vyplňuje většinu plátna: hvězdy planou uvnitř vířících svatozáří, měsíc hoří oranžově v rohu a uprostřed oblohy se valí velký spirálovitý proud. Dole mezi kopci spí tichá vesnice se špičatou věží kostela a podél levého okraje šlehá vzhůru tmavý cypřiš, to vše v hrubých, viditelných tazích modré a zlaté."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BIRTH_OF_VENUS"] =
    "Italská renesanční malba bohyně lásky přicházející z moře, jeden z nejslavnějších obrazů klasické mytologie. Venuše stojí nahá na obří lastuře hřebenatky a zakrývá se rukama a vlnou dlouhých zlatých vlasů. Vlevo ji dva okřídlení bohové větrů vanou ke břehu deštěm růžových růží, zatímco vpravo k ní pospíchá žena v květovaných šatech, aby ji zahalila do vlajícího pláště."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BINDO_ALTOVITI"] =
    "Italský vrcholně renesanční olejový portrét bohatého mladého římského bankéře. Pohledný mladík s dlouhými zlatými vlasy a černou čapkou se ohlíží přes své nahé rameno a hledí na tebe, jednu ruku přitaženou k hrudi. Má na sobě modrý plášť přes černý oděv a jeho bledá tvář září před hlubokým zeleným pozadím."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_DRAGON"] =
    "Raně italská renesanční malba se strnulým, pohádkově knižním půvabem. Vpravo obrněný rytíř na vzpínajícím se bílém koni vráží kopí do otevřené tlamy okřídleného zeleného draka se skvrnitými křídly jako z můry. Vlevo klidná princezna v dlouhých růžových šatech drží raněnou nestvůru na vodítku jako domácího mazlíčka před jejím tmavým doupětem, zatímco za rytířem se shromažďuje podivná spirálovitá bouře."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CREATION_OF_ADAM"] =
    "Italská renesanční freska ze stropu Sixtinské kaple, zdroj jednoho z nejslavnějších gest v umění. Nahý Adam leží vlevo na zeleném úbočí, jednu paži bezvládně nataženou, zatímco zprava se řítí Bůh, šedovousá postava ve vlající růžové říze plné andělů. Jejich natažené ukazováky se k sobě vztahují přes malou mezeru, okamžik před jiskrou života."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GALLERY_OF_THE_LOUVRE"] =
    "Americká olejomalba galerie v Louvru, namalovaná tím samým Morsem, který později vynalezl telegrafní kód. Velký salon s červenými stěnami je od podlahy ke stropu pokryt desítkami obrazů starých mistrů ve zlatých rámech, mezi nimi i drobná Mona Lisa. V popředí sedí studenti umění u stojanů a kopírují, zatímco jejich učitel se naklání přes rameno mladé ženy, aby opravil její práci, a v dálce se otevírá klenutá chodba dalších galerií."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WASHINGTON_CROSSING"] =
    "Hrdinná americká historická olejomalba, ikona války za nezávislost. Generál Washington stojí zpříma na přídi přeplněného veslového člunu, zatímco se jeho vojáci odrážejí bidly a veslují řekou ucpanou krami ledu, a za ním důstojník drží vysoko americkou vlajku. Světlo úsvitu proráží chladný opar a za nimi plují další čluny plné mužů a koní."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ARRANGEMENT_IN_GREY"] =
    "Americká olejomalba všeobecně známá jako Whistlerova matka. Starší žena v dlouhých černých šatech a bílém krajkovém čepci sedí v přísném profilu, otočená doleva, ruce složené v klíně a nohy na malé podnožce. Místnost je strohá a plochá: šedá stěna, tmavá vzorovaná záclona a jediný zarámovaný obraz, celá kompozice vyvážená jako studie v šedé a černé, přesně jak říká název."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BREEZING_UP"] =
    "Americká realistická olejomalba plachtění na malé lodi u pobřeží Nové Anglie. Muž a tři chlapci se opírají dozadu v malé plachetnici catboat jménem Gloucester, která se v silném větru naklání na bok; z přídě se tříští voda a u jejich nohou leží hromada denního úlovku. Moře je rozbouřené a zelené pod roztrhanými mraky, na obzoru je dvoustěžňová škuna."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_THOUSAND_LI"] =
    "Čínský vodorovný svitek s modrozelenou krajinou, malovaný na hedvábí dospívajícím zázračným talentem z dvora dynastie Song, dlouhý téměř dvanáct metrů. Hory v zářivé minerální modři a zeleni se zdvihají hřbet za hřbetem z klidné zlaté řeky, mezi svahy jsou ukryté drobné vesnice, mosty a holé stromy. Sloupce štětcem psané kaligrafie a červené sběratelské pečetě vyplňují oblohu nad vrcholy."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DWELLING_IN_THE_FUCHUN"] =
    "Čínský vodorovný svitek s tuší, mistrovské dílo krajinomalby učenců z doby dynastie Jüan, provedené výhradně v odstínech černé tuše na papíře. Zaoblené hory vystavěné z vrstvených suchých tahů štětce se zdvihají nad širokou klidnou řekou, podél břehů jsou borovice, roztroušené chaloupky a rybářské čluny. Nálada je nespěchavá a rozjímavá, papír je poset červenými sběratelskými pečetěmi, které za staletí nashromáždili obdivovatelé."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ALONG_THE_RIVER"] =
    "Čínský vodorovný svitek na hedvábí z doby dynastie Song, slavné panorama každodenního městského života dlouhé přes pět metrů. Zobrazený úsek se soustředí na velkou městskou bránu hlavního města, masivní dřevěnou věž na svažitém valu; ulice pod ní kypí životem: tržní stánky, volské povozy, velbloudí karavana procházející bránou a nosiči nesoucí náklad na ramenních tyčích. Každá postava je drobná, ale přesně nakreslená jemnou tušovou linkou v tlumených zemitých tónech."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LEAF_2"] =
    "Čínský list z alba z doby dynastie Čching, dvorní malba jemnou linkou a decentními barvami. Elegantní dámy v dlouhých splývavých rouchách bílé, zelené a modré barvy se shromažďují v zahradním pavilonu zahaleném jasně modrou látkou, jedna z nich pálí kadidlo u stolu za červeným zábradlím. Kolem nich jsou zahradní skály, bambus a kvetoucí popínavá rostlina šplhající přes střechu pavilonu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EMPEROR_TAIZONG"] =
    "Čínský vodorovný svitek na hedvábí z doby dynastie Tchang, dvorní záznam diplomatického setkání. Vpravo sedí císař Tchaj-cung na plošině, kterou nesou palácové dámy; ty také drží dva velké vějíře a nad ním červený baldachýn. Vlevo se v uctivých postojích blíží tři menší postavy: dvorní uvaděč v červeném, tibetský vyslanec ve vzorovaném rouchu a tlumočník v bílém, všichni na teplém zlatém hedvábí pokrytém červenými pečetěmi."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SPRING_MORNING"] =
    "Čínský vodorovný svitek na hedvábí z doby dynastie Ming, dlouhé panorama palácových žen ve chvílích oddechu za jarního rána. Desítky elegantních dam zaplňují otevřené sály, verandy a nádvoří: hrají hudbu, malují portrét, hrají si s dětmi a procházejí se mezi vrbami, zahradními skalami a dokonce i pávy. Palácová architektura se táhne po celé délce svitku v teplých červených a zelených tónech, každý paravan, zábradlí i roucho je vykresleno s pečlivým detailem jemné linky."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_GREAT_WAVE"] =
    "Japonský ukijo-e dřevořez, nejslavnější obraz japonského umění vůbec. Obrovská tmavomodrá vlna se vzpíná vlevo a převaluje se přes celou scénu, její hřeben se rozpadá do drápovitých prstů bílé pěny. Pod ní se na vlnových údolích houpají tři dlouhé otevřené čluny plné veslařů a daleko v dálce, malý uprostřed celé scény, se tyčí zasněžený kužel hory Fudži."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EVENING_SHOWER"] =
    "Japonský ukijo-e dřevořez, jedna z nejobdivovanějších scén deště, jaké kdy vznikly. Náhlý liják, zachycený jako závoje jemných šikmých čar, překvapil lidi uprostřed dlouhého dřevěného mostu; pospíchají oběma směry pod klobouky a deštníky, jeden se krčí pod slaměnou rohoží. Řeka pod mostem je pás zelenomodré barvy s osamělým vorařem, který se pohání bidlem, a vzdálený břeh se pod bouří rozplývá v tmavou šmouhu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_L_ABSINTHE"] =
    "Francouzská impresionistická olejomalba, nelítostná scéna z pařížského života v kavárnách. Žena v bledých šatech a klobouku sedí schlíple u mramorového kavárenského stolku se sklopenýma očima, před sebou sklenici mléčně zeleného absintu; vedle ní vousatý muž v pomačkaném kabátě zírá doprava s dýmkou v ústech. Oba sedí spolu, a přece zcela odděleně, namalováni v ošuntělých šedých a hnědých tónech, které obrazu dodávají atmosféru osamělosti."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_UPAUPA_SCHNEKLUD"] =
    "Postimpresionistický olejový portrét violoncellisty uprostřed hry. Hudebník se sklání nad svým jasně oranžovočerveným violoncellem, oči sklopené soustředěním, ruka se smyčcem přejíždí po strunách a jeho tmavomodrý oblek rámuje záři nástroje. Za ním se pozadí dělí na ploché oblasti hnědé a mechově zelené, posypané bledými abstraktními tvary, v Gauguinově odvážném, zjednodušeném barevném stylu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_BAR_AT_THE_FOLIES"] =
    "Francouzská olejomalba ze života moderní doby, Manetovo poslední velké dílo. Barmanka v černém sametovém živůtku s květinou na hrudi stojí za mramorovým pultem zaplněným lahvemi šampaňského, mísou pomerančů a sklenicí s růží a hledí ven s unaveným, vzdáleným výrazem. Za ní velké zrcadlo odráží třpytivý hudební sál s lustry a davem a, podivně posunutá doprava, i její vlastní záda, jak se naklání k muži v cylindru."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BALL_AT_THE_MOULIN"] =
    "Postimpresionistická olejomalba pařížského nočního života ve slavném kabaretu. Skupina mužů v cylindrech a žen v kloboucích s peřím sedí kolem stolu s nápoji, zatímco za nimi v zeleně osvětleném tanečním sále si zrzavá žena upravuje vlasy. U pravého okraje se tyčí ženská tvář osvětlená zespodu přízračnou zelenou barvou a přes popředí protíná dlouhé diagonální zábradlí v Lautrecově plakátovém stylu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS"] =
    "Vídeňská secesní olejomalba s vrstvami pravého plátkového zlata, Klimtovo nejslavnější dílo. Dvojice klečí v pevném objetí na rozkvetlé louce, muž se sklání, aby políbil ženu na tvář, zatímco ona se zavřenýma očima zvedá obličej vzhůru. Jejich těla splývají v jediný zlatý plášť vzorovaný obdélníky pro něj a zářivými kruhy pro ni, zářící na plochém třpytivém zlatém pozadí."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AMERICAN_GOTHIC"] =
    "Americká regionalistická olejomalba, nekonečně parodovaná a okamžitě rozpoznatelná. Přísný, plešatějící farmář v kulatých brýlích a džínových montérkách stojí a drží svisle vidle o třech hrotech, po jeho boku žena v tmavých šatech se vzorovanou zástěrou hledí stranou s našpulenou nespokojeností. Za nimi je bílý farmářský dům, podle kterého se obraz jmenuje, s gotickým oknem se špičatým obloukem ve štítu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SRI_SHANMUKAHA"] =
    "Indická zbožná malba v evropském akademickém stylu, který Ravi Varma proslavil po celé Indii. Hinduistický bůh Murugan jede na svém pávu se šesti korunovanými hlavami a mnoha pažemi držícími zbraně, po bocích ho doprovázejí dvě manželky v jasně růžových sárích. Pávův ocas se za nimi rozprostírá jako obří vějíř zelených a zlatých oček, zatímco pták tiskne pod nohama kobru k zemi."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DAUD_RECEIVES_A_ROBE"] =
    "Mughalská miniatura z ilustrované císařské kroniky, provedená krycími akvarelovými barvami a zlatem na papíře. Zobrazený výřez se soustředí na štíhlého mladého sluhu v bledém rouchu, červené čapce a zlaté šerpě, který nese složené zlaté čestné roucho pro obřad předání. Stojí před zářivě modrou stěnou stanu pokrytou jemnými kvetoucími popínavými rostlinami, každý záhyb i květ je vymalován s miniaturní přesností."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YUSEF_AND_ZULEYKHA"] =
    "Perská miniatura z ilustrovaného rukopisu, nejslavnější dílo velkého herátského mistra Behzáda. Stránku vyplňuje spletitý palác zobrazený v zploštělém průřezu, bludiště schodišť, balkonů a dveří obložených dlaždicemi v modré, oranžové a zlaté barvě. V horní komnatě prorok Jusuf, obklopený svatozáří z plamenů, prchá před Zulejchinou nataženou rukou, zatímco panely perské kaligrafie rámují architekturu."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ASCENT_OF_MUHAMMAD"] =
    "Perská miniatura z královského rukopisu zobrazující Prorokovu noční cestu nebesy. Mohamed, s tváří zahalenou bílým závojem a obklopenou zlatým plamenem, jede na Buráqovi, oři s lidskou hlavou, hlubokou modrou oblohou posetou stočenými mraky se zlatými okraji. Andělé v rouchách červené, zelené a oranžové barvy se kolem něj vznášejí ze všech stran a nesou dary a kadidelnice, přičemž scénu rámují řádky perské poezie."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LIBERTY_LEADING_THE_PEOPLE"] =
    "Francouzská romantická olejomalba, ústřední obraz revoluce. Svoboda sama, žena s obnaženými prsy ve žlutých šatech a červené čapce, kráčí přes barikádu z trosek a padlých těl a vztyčuje francouzskou trikolóru do zakouřené oblohy. Kolem ní se valí ozbrojení občané všech vrstev, mezi nimi pán v cylindru s mušketou a chlapec mávající dvěma pistolemi."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_JEROME_IN_HIS_STUDY"] =
    "Raně renesanční olejomalba pozoruhodné miniaturní přesnosti. Pohled vede velkým kamenným obloukem na svatého Jeronýma v červeném rouchu, který sedí a čte u dřevěné pracovny postavené jako jeviště uvnitř klenutého prostoru katedrály, obklopen policemi s knihami a hrnci. Světlo proudí dovnitř z oken na všech stranách, na prahu vpředu stojí páv a koroptev a jeho lev se plíží ve stínu vpravo."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PARTHENON_FRIEZE"] =
    "Viktoriánská olejomalba představující starověké Athény; ve hře toto dílo přichází spolu s divem Parthenón. Sochař Feidiás stojí na dřevěném lešení vedle svého čerstvě malovaného mramorového vlysu s jezdci, stále v barvách dílny, a přidržuje lano, zatímco dílo představuje. Malá skupina Athéňanů v řasených rouchách, mezi nimi Periklés, se naklání a v teplém světle uvnitř chrámu obdivuje řezbu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUE_DE_PARIS"] =
    "Francouzská realistická olejomalba moderní Paříže za mrholivého dne, ostrá a fotografická tam, kde byli jeho impresionističtí přátelé uvolnění. Dobře oblečený pár sdílející deštník kráčí k tobě po lesklé dlažbě, muž v cylindru a žena v dlouhých tmavých šatech s náušnicí, v níž se zachytává světlo. Kolem nich přecházejí další chodci s deštníky širokou křižovatku lemovanou klínovitými šedými činžovními domy, a zelený lampový sloup dělí scénu uprostřed na dvě poloviny."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_NIGHT_WATCH"] =
    "Nizozemská olejomalba zlatého věku v obrovském měřítku, nejslavnější skupinový portrét, jaký kdy vznikl. Městská domobrana se z hlubokého stínu dává do pohybu: kapitán v černém s červenou šerpou kráčí vpřed a vydává rozkaz svému poručíkovi v bledě zlatém, zatímco za nimi se nabíjejí muškety, zvedá se prapor a bubeník udává rytmus. Malá dívka v zářivých zlatých šatech tajemně svítí v davu, osvětlená jako reflektorem uprostřed šera."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DEATH_OF_MARAT"] =
    "Francouzská klasicistní olejomalba, velký obraz mučedníka Francouzské revoluce. Revoluční novinář Marat leží mrtvý ve vaně, schlíplý jako padlý světec, s hlavou ovinutou bílým turbanem a jednou paží visící k podlaze, přičemž ruka stále svírá brk. V druhé ruce drží dopis, jímž se jeho vrah dostal dovnitř; horní polovina plátna je holá tmavá stěna a prostá dřevěná bedna vedle něj nese namalované věnování 'A Marat, David.'"
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ETIENNE_CHEVALIER"] =
    "Francouzský pozdně středověký deskový obraz, jedno křídlo slavného zbožného diptychu. Královský pokladník Etienne Chevalier klečí v bohatém červeném rouchu se sepjatýma rukama k modlitbě, představen svým ochráncem svatým Štěpánem, který stojí vedle něj v modrozlatém oděvu. Světec drží knihu zakončenou drsným kamenem, symbolem svého mučednictví, a oba stojí v bílé mramorové síni s jménem donátora vytesaným podél stěny."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_FRANCIS"] =
    "Španělská barokní olejomalba strohé mnišské zbožnosti. Svatý František stojí sám v prosté kutně s kápí barvy písku, jeho tvář je napůl ztracená v hlubokém stínu kapuce, oči sklopené v modlitbě. V rukou chová lidskou lebku jako připomínku smrti, osvětlenou jediným tvrdým světlem na téměř černém pozadí."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HATAORI"] =
    "Japonský dřevořez ukijo-e zobrazující tkadlenu při práci. Mladá žena ve vzorovaném indigovém kimonu sedí bosa u velkého dřevěného ručního stavu a vzhlíží od práce, v jedné ruce drží člunek, a po celé délce stroje jsou napnuté nitě červené, modré a bílé. Barvy jsou jemné krémové a tlumené modré, se sloupcem štětcem psané básně vyplňujícím levou horní část listu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JANE_GREY"] =
    "Francouzská akademická historická malba, divadelní a srdceryvná. Mladá královna se zavázanýma očima, oblečená v bílém saténu, který září proti tmavé kamenné komnatě, klečí a slepě hmatá po popravčím špalku, zatímco starý úředník jí jemně vede ruce k němu. Její dvorní dámy se za ní v žalu hroutí u pilíře a kat čeká vpravo, opřený o sekeru, s očima odvrácenýma."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WANDERER"] =
    "Německá romantická olejomalba, ústřední obraz člověka o samotě před přírodou. Mladý muž v tmavě zeleném kabátě stojí zády k tobě na skalnatém vrcholu, opírá se o vycházkovou hůl a vítr mu cuchá vlasy. Pod ním moře bílé mlhy pohlcuje údolí, jen hřebeny a skalní štíty z ní vystupují jako ostrovy a bledé hory se ztrácejí v dálce."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BABEL"] =
    "Vlámská renesanční olejomalba biblické věže odsouzené k zániku, překypující podrobnostmi. Obrovská spirálová věž z oblouků, zčásti z bílého kamene a zčásti z syrových červených cihel, se nakřivo tyčí k oblakům a její vrchol je stále hrubý a nedokončený. U její paty se rozkládá přístavní město s loděmi na kotvách a v popředí král prohlíží skupinu kameníků, kteří mu klečí u nohou mezi svými kvádry."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YOUNG_LADY"] =
    "Raně nizozemský olejový portrét, malý, tichý a podivně moderní. Bledá mladá žena s tváří hladkou jako porcelán se na tebe dívá úkosem zpod vysoké černé sametové čelenky zdobené zlatem. Má modré šaty s bílým kožešinovým límcem a těsný náhrdelník ze zlatých a černých pásků, na pozadí obyčejné tlumené stěny namísto obvyklé tmavé prázdnoty."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_KINDRED"] =
    "Americká olejomalba školy řeky Hudson, hold přátelství mezi malířem a básníkem. Dva muži v kabátech stojí a hovoří na skalní římse, která vyčnívá nad zalesněnou roklí v pohoří Catskill, jeden z nich ukazuje štětcem k výhledu. Dole se přes kameny řítí potok, orámovaný obloukem převislých stromů, a za ním se ve zlatém světle rozplývají zamlžené štíty."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BLUE_BOY"] =
    "Anglický portrét olejem ve velkém stylu, nejslavnější dílo umělce. Chlapec asi dvanáctiletý stojí v celé postavě v třpytivém modrém saténovém obleku s kalhotami po kolena a krajkovým límcem, jednu ruku v bok, druhou drží u boku klobouk s pérem. S lehkou sebejistotou hledí z tmavé, bouřlivé hnědé krajiny, v níž modrý kostým přímo plane."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SECOND_OF_MAY"] =
    "Španělská olejomalba, jeden z prvních a největších protestů proti válce v umění. Ve světle lucerny stojí francouzská popravčí četa v řadě bez tváří, s puškami namířenými na hlouček španělských zajatců na holém pahorku za Madridem. Uprostřed muž v bílé košili rozpíná ruce před hlavněmi, klečí mezi těly již zastřelených a jeho póza připomíná ukřižování."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_CART"] =
    "Francouzská vojenská olejomalba z prusko-francouzské války, slavný obraz vzdorného posledního odporu. Hrstka francouzských vojáků brání rozbitý vesnický dům a střílí z okna, zatímco ranění sedí schlíplí u zdí a důstojník počítá jejich poslední náboje. Místnost je zdevastovaná, dveře vyvrácené z pantů, ze stropu padá omítka a dveřmi se valí denní světlo, kde dál bojují jejich druhové."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EARLY_AUTUMN"] =
    "Čínský vodorovný svitek v tuši a jemných barvách, detailní přírodní studie vadnoucího lotosového rybníka. Vážky v červené, zelené a modré se vznášejí nad schnoucím rákosím a potrhanými listy lotosů, zatímco pod nimi se věnují svým věcem kobylky, včela a malé žáby. Nálada je plná jemného zanikání, letní život pokračuje mezi rostlinami, které teprve začínají vadnout, a podél obou okrajů jsou červené sběratelské pečetě."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_APPRECIATING_LOTUSES"] =
    "Japonský závěsný svitek v tuši a barvách od zakladatele školy Kano, malovaný v čínském stylu učenecké krajiny. Čínský učenec v dlouhém rouchu pluje v malé loďce na okraji lotosového rybníka a hledí na plovoucí listy pod sukovitou vrbou, která se naklání ze skalnatého břehu. Většinu vysokého svitku tvoří mlha a otevřená voda, jen několik vrcholků borovic mizí v oparu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EQUESTRIAN_PORTRAIT"] =
    "Benátská renesanční olejomalba, vzor pro vládce na koni na celá staletí. Císař Svaté říše římské vyjíždí z temného lesa v plné lesklé zbroji a v přilbě s rudým chocholem, s kopím v ruce, na památku svého vítězství u Mühlbergu. Jeho černý kůň je zahalen do karmínové pokrývky a nízké večerní slunce probleskuje zlatě a růžově pod těžkými bouřkovými mraky."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ARMADA"] =
    "Tudorovský propagandistický portrét v oleji, namalovaný na oslavu porážky španělské Armady. Královna Alžběta sedí v obrovských šatech z perel a mašlí, její tvář orámovává rozlehlý bílý krajkový límec, jedna ruka majetnicky spočívá na glóbu a prsty má na Americe. Okny za ní se příběh odvíjí dvakrát: anglická flotila na klidném moři na jedné straně, španělské lodě rozbité bouří na druhé. Vedle ní leží její koruna zdobená drahokamy."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRANCIS_I"] =
    "Francouzský renesanční královský portrét v oleji. Král je k tobě obrácen od pasu nahoru, v nádherném dvorském oděvu, s rozstřihovanými rukávy z bílého a zlatého saténu s černými pruhy, se zlatým řetězem přes hruď a s černou čapkou s bílým perem na hlavě. Jeho vychytralá vousatá tvář s dlouhým nosem vynikne na karmínovém damaškovém pozadí se vzorem korun."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SELF_PORTRAIT"] =
    "Severní manýristický olejový autoportrét od vlámského dvorního malíře císaře Rudolfa II. Umělec se ohlíží přes rameno k tobě, statný vousatý muž s kudrnatými vlasy pod měkkou černou čapkou, v bílém nařaseném límci přes šedomodrý kabátec. Malba je teplá a přímá na prostém hnědém pozadí a jeho odhadující pohled úkosem poutá tvůj zrak."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VERTUMNUS"] =
    "Manýristická olejomalba, nejslavnější z Arcimboldových fantastických složených hlav. Je to portrét císaře Rudolfa II. jako římského boha ročních období, jehož celá tvář a hruď jsou složeny z ovoce, zeleniny a květin: víčka z hrachových lusků, nos z hrušky, rty z třešní, kníry z pšeničných klasů a vlasy z hroznů. Zdálky je to důstojný vládce, zblízka se rozplyne v tržní stánek, to vše na černém pozadí."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_SUPPER"] =
    "Benátská pozdně renesanční olejomalba, která znovu vymýšlí známý výjev. Stůl k večeři není obrácen čelně k tobě, ale prudce se noří v příkré úhlopříčce do temné hostinské síně, přičemž Kristus září zhruba v polovině její délky, když podává chléb apoštolům. V popředí služebníci nosí jídlo a kočka strká čumák do košíku, zatímco planoucí olejová lampa plní zakouřený vzduch nad nimi průsvitnými vířícími anděly."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_A_MAN"] =
    "Raně nizozemská olejomalba, možná umělcova vlastní tvář a jeden z prvních skutečných autoportrétů. Muž středního věku s vrásčitou tváří a bystrýma očima hledí přímo na tebe z hlubokého stínu, na hlavě má okázalou červenou pokrývku hlavy, omotanou a svázanou do sochařských záhybů. Detail je jehlově jemný, zachycena je každá vráska i každý chloupek strniště, postava je v tmavém kabátu lemovaném kožešinou na černém pozadí."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRONT_OF_THE_MIRROR"] =
    "Benátská renesanční olejomalba, poklidné pozdní mistrovské dílo stárnoucího Belliniho. Nahá mladá žena s kaštanově hnědými vlasy sedí na červené látce, klidně si upravuje vlasy a drží malé ruční zrcátko, zatímco druhé, kulaté zrcadlo na zdi za ní odráží zadní část její vzorované pokrývky hlavy. Okno vedle ní se otevírá do zelené krajiny se vzdálenými modrými horami pod oblačnou oblohou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ADORATION"] =
    "Raně italská freska z kaple Scrovegniů od malíře, jemuž se připisuje, že vrátil do západního umění přirozený lidský cit. Pod dřevěným přístřeškem drží Marie malého Krista, zatímco nejstarší ze tří králů klečí a líbá dítěti nohy, jeho koruna je odložena stranou, vlevo čekají velbloudi. Nad stájí přelétá hluboce modrou oblohou kometa místo obvyklé hvězdy, to vše v Giottových pevných, jednoduchých postavách a čistých barvách."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUBENS_AND_ISABELLA"] =
    "Vlámská barokní olejomalba, svatební portrét, na němž se umělec zobrazil se svou nevěstou. Mladý pár sedí těsně u sebe pod keřem zimolezu, její pravá ruka něžně spočívá na jeho ruce, což je tichý střed obrazu. On sedí nad ní v černém kabátci s přeloženou nohou, ona klečí ve fialové sukni, zlatem vyšívaném živůtku, se širokým límcem a vysokým slaměným kloboukem, oba hledí ven s klidnou spokojeností."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CHILDS_BATH"] =
    "Americká impresionistická olejomalba každodenní něhy, ovlivněná japonskými tisky vysokým úhlem pohledu a plochými vzory. Matka v šatech s výrazným pruhováním drží na klíně dítě zabalené do ručníku a myje mu nožičky v lavoru s vodou. Obě hlavy se naklánějí k sobě nad touto prací a pokoj kolem nich je jako patchworková přikrývka vzorů: květovaná tapeta, malovaná truhla, zdobený koberec a bílý džbán."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_CARD_PLAYERS"] =
    "Postimpresionistická olejomalba, jedna ze slavné série na toto téma. Dva sedláci v kloboucích sedí proti sobě u malého dřevěného stolu, pohlceni svými kartami, a mezi nimi stojí jediná láhev vína jako klidný střed kompozice. Jeden kouří dýmku, barva je nanášena trpělivými, hranatými tahy zemitě hnědé, okrové a tlumeně fialové, díky nimž postavy působí jako vytesané a trvalé."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_SWING"] =
    "Francouzská rokoková olejomalba, lehkovážná, tajnůstkářská a vůbec nejslavnější z obrazů své doby. V bujné zarostlé zahradě se mladá žena v nadýchaných růžových šatech houpe vysoko na provazové houpačce a kopnutím vyhazuje jednu pantofli do vzduchu, zatímco ukrytý starší muž tahá provazy ze stínu za ní. Její mladý milenec leží rozvalený v růžových keřích pod ní, dokonale umístěný, aby jí viděl pod sukně, a kamenná socha amorka si přikládá prst ke rtům."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIANT_MAGNOLIAS"] =
    "Americké zátiší v oleji, bujné a téměř tropické na pohled. Dva obrovské krémově bílé květy magnolie leží uříznuté na přehozu z hlubokomodrého sametu, obklopené svými lesklými tmavými listy, třetí poupě je stále zavřené. Okvětní lístky září na téměř černém pozadí, malované s voskovou, smyslnou přesností."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_KILLING"] =
    "Katalánský gotický deskový obraz v tempeře a zlatě. Svatý Jiří v černé zbroji se zlatou svatozáří se naklání ze vzpínajícího se bílého koně a zarazí dlouhé kopí dolů do otevřené tlamy draka s netopýřími křídly, země kolem nich je poseta kostmi a lebkami. Princezna v růžových šatech se modlí na skalnatém ostrohu vzadu a diváci se tlačí na bílých hradbách hradu nahoře."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JACQUES_AND_BERTHE"] =
    "Modernistický olejový dvojportrét sochaře Lipchitze a jeho ženy, malovaný v nezaměnitelném Modiglianiho stylu. Manžel stojí v tmavém obleku s rukou položenou na rameni své sedící ženy, jejíž růžolící tvář vystupuje z bílého krajkového límce. Oba mají umělcovy typické protáhlé tváře, dlouhé nosy a prázdné mandlové oči a jejich jména jsou naškrábána přes horní okraj plátna."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DASH_FOR_TIMBER"] =
    "Americký western, olejomalba, takový ten zuřivý akční výjev, který ve veřejné představě definoval Divoký západ. Osm kovbojů se žene přímo na tebe v plném trysku, kopyta koní se nedotýkají země, dva jezdci se v sedle otáčejí a střílejí zpět na skupinu apačských jezdců, kteří je v oblaku prachu pronásledují. Jeden raněný muž se svěšuje na druhého, zatímco se všichni řítí ke stromům na levém okraji vyprahlé pláně."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GEORGE_WASHINGTON_PORTRAIT"] =
    "Americký státní portrét, olej, oficiální podoba prvního prezidentství. Washington stojí v celé postavě v prostém černém sametovém obleku, jednu paži má nataženou v řečnickém gestu, v druhé drží slavnostní kordík, vedle stolu s brkem a kalamářem. Okolní výzdoba působí jako republikánská okázalost: pozlacená židle se štítem s hvězdami a pruhy, mramorové sloupy a záhyby karmínové drapérie, za níž se skrz bouřková mračna prodírá duha."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ATTACK_ON_BEIJING"] =
    "Japonský barevný tisk ve stylu válečné zpravodajské ilustrace, s popisky v japonštině i angličtině. Spojenecká vojska útočí na hradby císařského paláce v Pekingu: britští vojáci v červených kabátcích s britskou vlajkou se ženou z popředí, zatímco vpravo postupuje japonská pěchota v bílých uniformách. Výbuchy granátů visí jako bílé obláčky nad zeleným cvičištěm, za nimi je vidět brána paláce s modrou střechou a dýmající hradby."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUMO_WRESTLER"] =
    "Japonský ukiyo-e dřevořez, portrét slavného zápasníka, hvězdy své doby, mimo službu. Velký muž stojí v plné postavě v černém kimonu přes vzorované roucho, za pasem má meče, utírá si čelo kostkovaným kapesníkem a přes rameno nese svinutý plášť. Jeho jméno běží po pravé straně v řadě výrazných červených kaligrafických polí, postava je plochá a monumentální na prostém papíře."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_TIGER_IN_TROPICAL_STORM"] =
    "Naivní olejomalba od samouka, francouzského celního úředníka, který nikdy neviděl džungli. Tygr s vytřeštěnýma očima se krčí nízko v dlouhé trávě ohýbané větrem, s vycenými zuby, zachycený v bouři, která ohýbá každou rostlinu do strany. Džungle je hustý vzor stylizovaných listů v zelených a červených odstínech a šikmé stříbrné pruhy deště jsou nakresleny přes celé plátno jako závoj."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_HOME_GUARD"] =
    "Maďarský olejový portrét ve stylu biedermeieru z revoluce roku 1848. Vousatý občan-voják sedí v prosté nebarvené plátěné bundě, obě ruce v rukavicích spočívají na jílci vzpřímené šavle, na rukávu má červeno-bílo-zelenou národní pásku, která hlásí jeho věc. Hledí stranou s klidným odhodláním, vřele osvětlen před tmavě červenou oponou, jeho kabát s červenou podšívkou je přehozen přes židli."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CEREMONIAL_SITTING"] =
    "Ruská realistická olejomalba obrovských rozměrů, skupinový portrét celé vládní rady říše. Desítky starých státníků v tmavých uniformách těžkých od zlatého prýmkování a s červenými šerpami sedí kolem velkého podkovovitého uspořádání červených židlí v sále s bílými sloupy, kde visí lustry a portréty členů carské rodiny. Každá z více než šedesáti tváří je samostatný portrét, namalovaný s Repinovým rychlým, sebejistým realismem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUSSIAN_TSAR"] =
    "Ruská historická olejomalba znovu vytvářející královský průvod ze šestnáctého století. Car v kožešinové čepici, v rouchu ze zlatého brokátu, jede na bílém koni sněhem, před ním jdou strážci v zářivě červených kabátech s vysokými zakřivenými sekerami na dlouhých násadách. Dav klečí a sklání se až k zemi po obou stranách udusané zasněžené cesty, v pozadí jsou srubové stavby starého ruského města pod bledou zimní oblohou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CRUCIFIXION_OF_SAINT_PETER"] =
    "Italská barokní olejomalba, krutá a tělesná v Caravaggiově typickém stylu. Tři dělníci se namáhají, aby zvedli dřevěný kříž, na který byl hlavou dolů přibit starý svatý Petr, jeden tahá za lano, další se krčí pod břevnem, jejich tváře nejsou vidět. Bělovousý světec zvedá hlavu, aby se podíval na vlastní přibitou ruku, jeho svalnaté staré tělo září z naprosté tmy v jediném tvrdém světle."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LANDSCAPE_WITH_ANT_BEAR"] =
    "Nizozemská koloniální krajina, olejomalba, kterou namaloval první v Evropě vyškolený umělec působící v Brazílii. Široké slunné údolí s řekou se otevírá pod velkou oblohou mezi dvěma vysokými palmami, na vzdálených kopcích stojí koloniální osada bílých domů. V popředí kráčí po cestě skupina afrobrazilských postav s uzlíky v rukou a mravenečník s dlouhým rypákem, o němž je řeč v názvu, čenichá v křoví vpravo dole."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DUTCH_MEN_O_WAR"] =
    "Nizozemská námořní olejomalba ze zlatého věku od největšího malíře lodí své doby. Vysoké dřevěné válečné lodě kotví na vodě hladké jako sklo, jejich plachty visí ochable a trupy se zrcadlí v moři, každé lano lanoví je přesné. Veslice převážejí cestující mezi plavidly pod rozsáhlou oblohou ozářených kupovitých oblaků, celý výjev je zalit zlatým klidem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HARBOR_IN_BALAKLAVA"] =
    "Kolorovaná litografie z krymské války, nakreslená jedním z prvních válečných umělců, kteří dokumentovali tažení přímo na místě. Na pustém břehu přístavu pomáhají nemocným a raněným vojákům zabaleným v bílých dekách z nosítek nesených na mulách do čekající veslice. Za hloučkem postav se zvedají holé hnědé kopce, svah je posetý armádními boudami a stany, barvy jsou tlumené a dokumentární."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PEACEMAKERS"] =
    "Americká historická olejomalba skutečné porady z občanské války v jejích posledních dnech. Prezident Lincoln sedí v kajutě parníku a soustředěně naslouchá s bradou opřenou o ruku, zatímco generál Sherman uprostřed řeči gestikuluje, generál Grant a admirál Porter doplňují kruh čtyř postav v tmavých oblecích. Okny kajuty za nimi se prodírá duha skrz vyjasňující se oblohu, tichý znak blížícího se míru."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_CHITASEI"] =
    "Japonský ukiyo-e dřevořez z Kuniyošiho slavné série 108 hrdinů čínského románu Příběhy od jezerního břehu. Učenec a stratég Wu Yong stojí ve splývavém tmavém rouchu se vzorem draků a v zamyšlení si hladí vousy pod noční oblohou posetou hvězdami. Vedle něj sedí velký nebeský glóbus na ozdobném stojanu a postavu obklopují pole s japonským textem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_LOUIS"] =
    "Anglický olejový portrét z osmnáctého století zachycující sochaře při práci. Roubiliac, v měkké čepici a s otevřenou košilí se vyhrnutými rukávy, se zastavil se zdviženým modelovacím nástrojem a hledí stranou, zatímco pracuje na hliněné sošce Shakespeara na podstavci. Volnou rukou sochař ukazuje na své dílo, vřele osvětlen před tmavým pozadím ateliéru."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_NASSER"] =
    "Perský dvorní portrét z doby Kádžárovců, olejomalba, královská nádhera nanesená vrstvu na vrstvu. Mladý šáh s knírem sedí strnule vzpřímeně v šarlatové uniformě posázené zlatým vyšíváním, s provazci perel, ozdobnými nárameníky s drahokamy a modrou šerpou, jednou rukou se opírá o meč zdobený drahokamy. Nosí vysoký černý klobouk s kyticí diamantů, jeho tmavě orámované oči hledí ven na hluboké olivové pozadí s vyraženým královským nápisem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FIELD_WITH_SHEAFS"] =
    "Německá krajina ve stylu blízkém expresionismu, olejomalba provedená širokými, energickými tahy. Sklizené pšeničné pole vyplňuje popředí řadami zlatých snopů naskládaných do nakloněných svazků, žlutá je nanesena tlustě a zářivě. Řada tmavozelených stromů uzavírá pole, nad nímž se klene světle fialovomodrá obloha s větrnými mraky."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AT_THE_EDGE_OF_THE_BROOK"] =
    "Francouzská akademická olejomalba, vyleštěná do sklovité dokonalosti, kterou byl Bouguereau proslulý. Dvě bosé selské děti sedí na kameni na okraji potoka, mladší dívka si stahuje punčochu, zatímco její tmavovlasá společnice si zvedá sukni, aby se brodila vodou. Vyměňují si pohled uprostřed rozhovoru, jejich pleť a rozcuchané vlasy jsou vymalovány s fotografickou hladkostí na pozadí měkké venkovské krajiny."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS_ALT"] =
    "Italská romantická olejomalba, nejslavnější polibek italského umění a skrytý vlastenecký symbol sjednocení. Ve středověké kamenné chodbě mladý muž v klobouku s pérem a hnědém plášti ohýbá ženu dozadu ve vášnivém polibku, jednu nohu už na schodu, jako by se v útěku na okamžik zastavil. Její světle modré saténové šaty vlévají do výjevu světlo, zatímco za průchodem se blíží stínová postava."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MOVING_HOUSE"] =
    "Ruská realistická olejomalba tiché městské chudoby. Starý pár se vleče po zamrzlém ledu řeky v Petrohradě a nese všechno, co mají, v látkovém uzlu, muž se opírá o hůl, oba jsou zabaleni do obnošených kabátů a šátků proti zimě. Malý pes klusá před nimi a zlacená věž Petropavlovské pevnosti se za nimi vypíná zimním oparem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MEXICAN_EXPEDITION"] =
    "Francouzská námořní historická olejomalba, reportážního stylu a plná děje. Francouzská válečná loď s trikolorou ovládá levé popředí, důstojníci na její palubě řídí bombardování mexické pevnosti San Juan de Ulúa, nad vodou stoupá kouř. Granáty dopadají do vody poblíž veslic, které převážejí muže mezi loděmi, na zamlženém obzoru je vidět sopku se zasněženým vrcholem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_DAY_OF_POMPEII"] =
    "Ruská romantická olejomalba na obrovském plátně, katastrofický epos svého století. Obloha nad Pompejemi hoří červeně a černě, jak Vesuv soptí, sochy se hroutí ze střechy a blesk rozráží oblak popela. Davy obyvatel v římském oděvu prchají padajícími troskami, děti a staré lidi chrání pod plášti, zatímco uprostřed leží rozvalená padlá žena vedle převráceného vozu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ACCOLADE"] =
    "Anglická olejomalba v duchu prerafaelitů, pohádková vize rytířství. Zlatovlasá královna ve splývavých bílých šatech se dotýká mečem ramene klečícího rytíře a pasuje ho před malým dvorním obecenstvem. Rytíř sklání hlavu v kroužkové košili a červeném přehozu, helmu má na podlaze vedle sebe, kamenný sál a červené pódium jsou namalovány v zářivých romantických detailech."
